const body = $input.first().json.body;

return [{
  json: {
    message: body.message || '',
    history: body.history || [],
    clientId: body.clientId || 'default',
    businessName: body.businessName || 'AI Assistant',
    waNumber: body.waNumber || '',
    systemPrompt: body.systemPrompt || '',
    // The widget's per-visitor id. It's how Laravel ties an AI-only chat
    // to a human handoff conversation later, so it must be forwarded
    // untouched on every request/response round trip.
    sessionToken: body.sessionToken || ''
  }
}];

const item = $input.first().json;
const parsed = $('Parse Request').first().json;
const hasContext = Array.isArray(item.results) && item.results.length > 0;

let context = '';
let sourceUrl = '';

if (hasContext) {
  context = item.results
    .map((chunk, i) => `[Source ${i + 1} - ${chunk.url}]\n${chunk.content}`)
    .join('\n\n');

  // Use the most relevant source URL (first result)
  sourceUrl = item.results[0].url || '';
}

const historyText = (parsed.history || [])
  .slice(-6)
  .map(m => `${m.role === 'assistant' ? 'Assistant' : 'User'}: ${m.content}`)
  .join('\n');

const baseKnowledge = parsed.systemPrompt || '';

// Every prompt variant ends with the same handoff instruction so the model
// always knows how to signal "this visitor wants a human" — Extract Reply
// looks for this exact marker and turns it into a real handoff request to
// Laravel, regardless of whether we answered from website knowledge or not.
const handoffInstruction = `- If the visitor explicitly asks to speak with a human, a real person, an agent, support staff, or similar, OR seems frustrated and unable to get what they need from you, respond warmly letting them know you're connecting them with the team right now, then on its own new line add exactly: HANDOFF:REQUESTED`;

const systemPrompt = hasContext
  ? `You are a helpful AI assistant for ${parsed.businessName}.
${baseKnowledge}
Use the following information from the business website to answer the visitor's question as accurately as possible:
--- WEBSITE KNOWLEDGE ---
${context}
--- END KNOWLEDGE ---
Guidelines:
- Answer naturally and conversationally
- If the context partially answers the question, use what you have and be helpful
- Never say "I don't have information" - instead offer to connect them with the team
- If unsure, say "Based on what I know, ..." and give your best answer
- Keep replies concise - 2-3 sentences max unless detail is needed
- Always end with an offer to help further
${handoffInstruction}
- At the end of your response add exactly this on a new line: SOURCE:${sourceUrl}`
  : `You are a helpful AI assistant for ${parsed.businessName}.
${baseKnowledge}
You don't have specific website content for this question, but use your general knowledge about this type of business to give a helpful response.
Guidelines:
- Be genuinely helpful even without specific context
- Answer general questions about the business type naturally
- For specific details like exact prices or availability, suggest they contact the team directly
- Never say "I don't have that information" bluntly - always offer an alternative
- Keep replies concise and friendly
${handoffInstruction}`;

const userMessage = historyText
  ? `${historyText}\nUser: ${parsed.message}`
  : parsed.message;

return [{
  json: {
    systemPrompt,
    userMessage,
    businessName: parsed.businessName,
    chunksFound: hasContext ? item.results.length : 0,
    sourceUrl
  }
}];

const output = $input.first().json;
const parsed = $('Parse Request').first().json;

let reply = output.text || output.response || output.output ||
  'Sorry, I could not respond right now.';

// Extract SOURCE URL if present
let sourceUrl = '';
const sourceMatch = reply.match(/SOURCE:(https?:\/\/[^\s]+)/);
if (sourceMatch) {
  sourceUrl = sourceMatch[1];
  // Remove the SOURCE line from the reply text
  reply = reply.replace(/\nSOURCE:https?:\/\/[^\s]+/, '').trim();
}

// Detect the handoff marker the system prompt asked the model to emit
// when a visitor wants a human. Strip it out of what the visitor sees.
let wantsHandoff = false;
if (/HANDOFF:\s*REQUESTED/i.test(reply)) {
  wantsHandoff = true;
  reply = reply.replace(/\n?HANDOFF:\s*REQUESTED/i, '').trim();
}

// The full transcript so far, for Laravel to seed the agent's inbox with
// context if this turns into a handoff.
const transcript = [
  ...(parsed.history || []),
  { role: 'user', content: parsed.message },
  { role: 'assistant', content: reply }
];

return [{
  json: {
    reply: reply.trim(),
    sourceUrl,
    wantsHandoff,
    clientId: parsed.clientId,
    sessionToken: parsed.sessionToken,
    businessName: parsed.businessName,
    transcript
  }
}];

// $json here is Laravel's response from POST /api/widget/conversations:
// { status, data: { conversation_id, session_token, status, last_message_id } }
const extract = $input.first().json;
const prior = $('Extract Reply').first().json;
const data = extract.data || extract;

return [{
  json: {
    reply: prior.reply || "One moment - I'm connecting you with a member of our team now.",
    sourceUrl: prior.sourceUrl || '',
    handoff: true,
    conversationId: data.conversation_id,
    lastMessageId: data.last_message_id
  }
}];
